      "O Palácio de Hamiel parecia grande demais até para alguém que já havia caminhado por lugares celestiais. Sete andares compunham apenas a estrutura principal, e os corredores eram cobertos por bandeiras vermelhas, armaduras antigas e retratos de guerreiros que haviam carregado o símbolo do Leão Vermelho por gerações.",
      "Kaizen acompanhava Elisabeth em silêncio. Os cabelos brancos e os olhos de cores diferentes chamavam atenção por onde passava, embora nada além disso denunciasse o que ele realmente era. As asas haviam desaparecido. As runas estavam inativas. Alfa, Ômega e Beta não respondiam. O corpo sentia frio, fome e cansaço como o de qualquer homem comum.",
