      "Kaizen olhou para o número.",
      "— Parece correto.",
      "— Você não vai se defender?",
      "— Do cristal?",
      "Grifim estreitou os olhos.",
      "Elisabeth interrompeu antes que aquilo virasse confronto. Hamiel não manteria dois invocados. Um serviria ao reino; o outro teria de deixar o castelo. A frase saiu fria, mas Kaizen percebeu algo que Grifim não percebeu: preocupação. Elisabeth não queria mandar um fraco para uma guerra que poderia matá-lo.",
      "O rei Bardragon apareceu pouco depois. Mesmo envelhecido e marcado por ferimentos da última guerra, o Leão Vermelho ainda fazia o salão parecer menor. Cabelos e barba vermelhos, armadura pesada e mãos capazes de carregar o chamado Fogo do Sol. Ao lado dele, Amelia Hamiel, a Dançarina da Espada, observava tudo com calma. Layla, irmã mais nova de Elisabeth, não tinha a mesma delicadeza.",
