      "Foi ali também que Kaizen conheceu Elises Elfenhard, comandante de Hamiel. Cabelos e olhos verdes, orelhas élficas e a postura de alguém que media cada movimento. Ela viera do Reino de El, lar de Vana Ygradrasil, a árvore sagrada ao redor da qual uma civilização inteira havia crescido.",
      "Elisabeth explicou que a Floresta Proibida protegia El. Quem entrava com intenção maligna podia jamais retornar. Quem não representava ameaça era devolvido para a saída sem sequer compreender como.",
      "— Parece uma floresta temperamental — disse Kaizen.",
      "Elises ergueu uma sobrancelha.",
