      "Ao final do dia, Grifim possuía uma classe SS, milhares de pontos de energia e expectativas sobre os ombros.",
      "Kaizen tinha doze.",
      "Pela primeira vez em muito tempo, ninguém tinha motivo para ter medo dele.",
      "E, estranhamente, ele gostava disso."
