    "title": "A Princesa-Regente",
    "paragraphs": [
      "No sexto mês sem Kaizen, duas fortalezas da fronteira oeste foram abandonadas. Cento e sete soldados morreram. Quase seiscentos foram retirados.",
      "Elisabeth recebeu a notícia durante o jantar.",
      "— Foi erro meu.",
      "Bardragon não a protegeu da verdade.",
      "— Sim.",
      "Layla levantou o rosto.",
      "Amelia permaneceu quieta.",
      "— Agora vai passar a noite se culpando ou aprender por que errou?",
      "Elisabeth respondeu:",
      "— Os dois.",
      "Bardragon sorriu.",
      "— Agora parece minha filha.",
      "Naquela noite, Elisabeth abriu mapas e livros. Estratégia militar deixou de ser suficiente. Economia. Agricultura. Diplomacia. Logística. Cultura. Magia territorial. Religiões vizinhas.",
      "Percebeu que um governante não vencia guerra apenas escolhendo onde soldados lutavam. Precisava garantir comida três meses depois, estradas abertas, aliados presentes e uma população que ainda acreditasse que valia a pena continuar.",
      "Elises voltou duas semanas depois e encontrou Elisabeth acordada às duas da manhã.",
      "— Dormiu ontem?",
      "Silêncio.",
      "— Quantas horas?",
      "— Duas.",
      "Elises fechou o livro.",
      "— Cama.",
      "— Tenho trabalho.",
      "— Cama.",
      "— Você não manda em mim.",
      "Elises começou a arrastar a cadeira.",
      "— ELİSES.",
      "Layla apareceu com uma vela.",
      "— Posso ajudar?",
      "— Pega os livros — respondeu Elises.",
      "— TRAIDORAS.",
      "No campo, Elisabeth também intensificou treinamento. Amelia corrigia técnica. Elises cobrava combate. Bardragon gritava da varanda.",
      "— MAIS FORTE!",
      "— VOCÊ ESTÁ SENTADO!",
      "— EXPERIÊNCIA!",
      "Quando tentou levantar para demonstrar, Amelia segurou sua capa.",
      "— Senta.",
      "O Leão Vermelho sentou imediatamente.",
      "— Sim, querida.",
      "Elises riu.",
      "Elisabeth quase recebeu uma espada no rosto por perder concentração.",
      "Dois mundos treinavam ao mesmo tempo.",
      "Dentro do Breu, Kaizen aprendia a controlar existência.",
      "Fora dele, Elisabeth aprendia a carregar um reino."
    ],
