      "No quarto ano, Grifim recebeu autorização para comandar uma divisão.",
      "Ficou insuportável.",
      "— General Grifim.",
      "Elises passou por ele.",
      "— Não.",
      "— É meu cargo.",
      "— Sou comandante do exército.",
      "Grifim pensou.",
      "— Bom argumento.",
      "Entrou na sala estratégica.",
      "— Pimenta Vermelha.",
      "Elisabeth nem levantou a cabeça.",
      "— Quer morrer hoje?",
      "— Princesa-Regente.",
      "— Melhor.",
      "Elises entrou.",
      "— Elfa Demoníaca.",
      "Ela sorriu.",
      "— Continue.",
      "— Comandante Elises.",
      "— Excelente.",
      "Apesar das provocações, a reunião era séria. Uma fortaleza precisava ser retomada. Grifim sugeriu ataque frontal. Elises, infiltração.",
