      "— Henrique sempre foi Kaizen. Não com esse nome, cabelo ou olhos. Mas era ele.",
      "Elisabeth quis saber como ele era antes.",
      "Teimoso. Engraçado, ou achava que era. Inseguro. Com medo de falhar e de não conseguir cuidar de todos.",
      "— Isso não mudou — percebeu Elisabeth.",
