      "Elises girou e parou a lâmina no pescoço dele.",
      "— Morto.",
      "Grifim suspirou.",
      "— Você é irritante.",
      "— Aprendi com alguém.",
      "Os dois sabiam quem.",
      "Depois conversaram sobre Kaizen. Grifim reclamou que havia treinado cinco anos, ultrapassado sessenta mil pontos e provavelmente encontraria o outro saindo do Breu com doze.",
      "— E ainda vai me irritar.",
      "— Com certeza — respondeu Elises.",
