      "Kaizen começou a perder paciência.",
      "Arcaceus pegou uma pedra natural. Irregular, manchada, rachada.",
      "Ao lado, colocou a pedra criada por Kaizen: simétrica, lisa, impecável.",
      "— Qual parece real?",
      "— A feia.",
      "Escuridão riu.",
