      "Elisabeth voltou à Ponte das Fitas sozinha.",
      "Levava as duas fitas de Mira.",
      "Sentou perto da fonte observando casais até uma senhora desconhecida comentar:",
      "— Ainda não encontrou ninguém?",
      "— Desculpa?",
      "— Essa cara. De quem chama de bobagem porque gostaria de ter motivo para fazer igual.",
