    "title": "O Último Rei Antes da Rainha",
    "paragraphs": [
      "Bardragon começou a ensinar Elisabeth como morrer.",
      "Ela recusou imediatamente.",
      "— Não.",
      "— Nem sabe o que vou dizer.",
      "— Sei pela sua cara.",
      "— Que cara?",
      "— Cara de velho prestes a falar algo profundo.",
      "Ele começou a rir.",
      "Sentaram numa varanda.",
      "Bardragon mostrou o selo real.",
      "— Um rei passa a vida achando que isso significa poder. Também. Mas principalmente significa decisões que ninguém quer tomar.",
      "Fome. Alianças quebradas. Soldados heróis cometendo crimes. Escolhas onde toda alternativa custava vidas.",
      "— Vai cometer erros. Vai matar pessoas com decisões. Vai salvar outras sem nunca saber.",
      "Elisabeth riu sem humor.",
      "— E dormir mal.",
      "— Isso já faço.",
      "— Excelente preparação.",
      "Ela perguntou por que falava como se fosse morrer amanhã.",
      "— Se eu esperar o dia anterior, provavelmente estarei ocupado morrendo.",
      "Elisabeth bateu no braço dele.",
      "Depois Bardragon perguntou:",
      "— Gosta dele?",
      "— Não vamos conversar sobre isso.",
      "— Então sim.",
      "— PAI.",
      "— Estou velho. Tenho direito.",
      "— Não tem.",
      "Bardragon falou de Kaizen: estranho, aparentemente fraco, respeitoso quando queria, e alguém que olhava para Elisabeth sem ver uma coroa.",
      "— Isso é raro.",
      "— Eu sei.",
      "Amelia tivera isso com Bardragon antes do trono.",
      "Uma voz veio de dentro do quarto:",
      "— AINDA CHAMO ELE DE IDIOTA.",
      "Bardragon gritou:",
      "— ESTÁ OUVINDO?!",
      "— VOCÊ FALA ALTO.",
      "Elisabeth riu.",
      "Bardragon guardou o anel.",
      "— Ainda não. O trono continua sendo meu problema. Mas, se um dia eu não levantar, não fique esperando minha cadeira como espera a dele.",
      "Elisabeth perdeu o sorriso.",
      "— Promete.",
      "Longo silêncio.",
      "— Prometo.",
      "— Boa rainha.",
      "— Princesa.",
      "— Por enquanto."
    ],
