    "id": "capitulo-189",
    "number": 189,
    "book": 2,
    "title": "A Primeira Noite sem Correntes",
    "paragraphs": [
      "Ariane passou quatro dias na floresta.",
      "No primeiro, liberdade.",
      "No segundo, fome.",
      "No terceiro, medo.",
      "No quarto, entendeu que fugir era só a primeira parte.",
      "Escutou cavalos e viu os mercenários procurando. O homem que roubara sua medalha ainda a carregava.",
      "Raiva fez o colar aquecer.",
      "Ariane respirou e controlou.",
      "Não agora.",
      "Horas depois, seguiu as pegadas dos próprios caçadores. Encontrou o acampamento à noite.",
      "A medalha estava numa bolsa.",
      "Deveria ir embora.",
      "Mas uma lembrança surgiu: uma mulher desfocada colocando o símbolo em seu pescoço.",
      "Nunca perde isso.",
      "Ariane esperou os homens dormirem e rastejou até a bolsa.",
      "Pegou a medalha.",
      "Uma mão agarrou seu braço.",
      "— Te achei.",
      "O vigia fingira estar bêbado.",
      "Os outros começaram a acordar.",
      "O colar brilhou.",
      "Dor.",
      "Medo.",
      "Raiva.",
      "Crack.",
      "Uma runa do colar rachou.",
      "Os olhos de Ariane brilharam dourados. Escamas vermelhas surgiram pelos braços.",
      "— SOLTA.",
      "A voz pareceu maior que a criança.",
      "Uma explosão dourada lançou o mercenário e queimou as tendas.",
      "Ariane caiu, fraca.",
      "Mas correu novamente.",
      "Desta vez com a medalha.",
      "Muito longe, o dragonoide de chifres negros caiu de joelhos.",
      "— Ela quebrou parte do selo.",
      "— Sentiu?",
      "Ele sorriu com lágrimas nos olhos.",
      "— Tenho uma direção. Finalmente.",
      "Ariane corria sem saber que alguém a procurava.",
      "Não sabia que o símbolo significava realeza.",
      "Só sabia que recuperara algo seu."
    ],
