    "images": [],
    "title": "O Leão que Ainda Tinha Dentes",
    "paragraphs": [
      "Bardragon estava oficialmente proibido de lutar.",
      "Ele considerava aquilo uma opinião médica.",
      "Amelia o encontrou no pátio vestindo armadura e segurando espada.",
      "Três soldados próximos pareciam prestes a pedir transferência.",
      "— Bardragon.",
      "O rei congelou.",
      "— O que está fazendo?",
      "Ele olhou para a própria armadura.",
      "— Caminhada.",
      "— Com armadura de guerra?",
      "— Está frio.",
      "— E espada?",
      "— Animais.",
      "— Dentro do Palácio?",
      "— Nunca se sabe.",
      "Amelia estendeu a mão.",
      "— Espada.",
      "— Sou o Rei de Hamiel.",
      "— E eu sou a mulher que sabe onde seus medicamentos estão.",
      "Bardragon ficou quieto.",
      "Entregou.",
      "Elisabeth e Layla observavam da varanda.",
      "— Mamãe é assustadora — disse Layla.",
      "— Sim.",
      "— Mais que você?",
      "Elisabeth pensou.",
      "— Sim. Não repete.",
      "Apesar do humor, Bardragon piorava. Alguns dias eram bons. Outros, cada passo parecia cobrar décadas de guerra.",
      "Naquela tarde, conseguiu caminhar até a muralha principal com Elisabeth.",
      "— Não precisa ficar me seguindo.",
      "— Sou sua escolta.",
      "— Você tem um reino para administrar.",
      "— Deleguei.",
      "Bardragon sorriu.",
      "— Finalmente.",
      "Lá de cima, observou Hamiel.",
      "— Mudou.",
      "— Muito.",
      "— Você mudou mais.",
      "Elisabeth perguntou se isso era bom.",
      "— Ainda decidindo.",
      "Falou sobre o próprio pai e sobre o medo que sentira quando herdara o trono. Sabia lutar, comandar e vencer batalha, mas governar era diferente. Num campo de batalha, o inimigo normalmente estava do outro lado. Num reino, alguém que discordava hoje poderia salvá-lo amanhã; alguém sorrindo agora poderia estar roubando celeiros.",
      "— Não vire uma rainha que só confia em si mesma.",
      "Elisabeth negou que fizesse isso.",
      "Bardragon simplesmente olhou.",
      "— Talvez um pouco — admitiu.",
      "Ele enumerou Amelia, Elises, Layla e até Grifim.",
      "— E Kaizen ajudava.",
      "Elisabeth ficou quieta.",
      "— Sim.",
      "— Mesmo com doze pontos.",
      "Ela riu.",
      "— Principalmente com doze.",
      "Bardragon perguntou se ainda esperava.",
      "— Sim.",
      "Ela respondeu antes de pensar.",
      "— Bom.",
      "Elisabeth se surpreendeu.",
      "— Esperança não é fraqueza. Só não deixe virar prisão. Se ele voltar, viva. Se não voltar… viva também.",
      "Elisabeth odiava quando o pai dizia coisas certas.",
      "O Leão Vermelho ainda tinha dentes.",
      "Mesmo quando já não podia usá-los em guerra."
    ]
