      "Joren começou a rir.",
      "— Surpreendentemente correto.",
      "Ariane não aceitou ir.",
      "Ainda.",
      "Mas naquela noite repetiu o nome para si mesma.",
      "— Hamiel.",
      "Era apenas uma palavra.",
