    "title": "O Primeiro Mundo de Arcaceus",
    "paragraphs": [
      "Kaizen sentou imediatamente.",
      "— História.",
      "Luz e Escuridão fizeram o mesmo.",
      "Arcaceus percebeu que perdera a votação.",
      "Mostrou sua primeira dimensão particular. Pequena. Criada quando ainda aprendia.",
      "— Quanto tempo levou?",
      "— Uns vinte mil anos.",
      "Kaizen engasgou.",
      "— VINTE MIL?",
      "— Eu estava aprendendo.",
      "O jovem Arcaceus usava a dimensão para guardar pedras, ferramentas, cristais, experimentos e até fragmentos de estrelas. Com o tempo, adicionou regras. Espaço. Tempo. Estabilidade. Energia.",
      "O depósito virou região.",
      "Depois mundo.",
      "Depois universo.",
      "— Ainda existe? — perguntou Kaizen.",
      "Arcaceus demorou.",
      "— Existe.",
      "A memória mostrou estrelas, planetas, civilizações e um palácio flutuante construído pelo primeiro filho.",
      "— Bonito — disse Kaizen.",
      "— Gostava de ficar lá.",
      "— Sozinho?",
      "Arcaceus hesitou.",
      "Kaizen abriu um sorriso.",
      "— Tem mulher nessa história.",
      "Escuridão e Luz concordaram imediatamente.",
      "A memória mudou para uma floresta de teias negras e flores vermelhas.",
      "Uma mulher apareceu. Corpo majoritariamente humano, cabelos negros, olhos vermelhos, pequenas marcas próximas ao rosto e membros de aranha que podiam se abrir pelas costas. Em algumas formas, a parte inferior do corpo assumia aspecto de viúva-negra.",
      "Letal.",
      "Elegante.",
      "E, naquele momento, carregando uma cesta.",
      "— Você esqueceu de comer novamente — disse ela ao jovem Arcaceus.",
      "— Tecnicamente não preciso.",
      "— Tecnicamente continua sendo idiota.",
      "Kaizen começou a rir.",
      "— Eu gosto dela.",
      "O nome era Nyssara.",
      "Ela podia paralisar guerreiros, criar teias mágicas e sentir vibrações a enormes distâncias. Ao mesmo tempo, costurava mantas, levava comida para Arcaceus e sentava ao lado dele enquanto criava.",
      "— Você gostava dela — percebeu Kaizen.",
      "— Sim.",
      "— Amava?",
      "Arcaceus ficou quieto.",
      "— Eu não sabia o que era isso. Gostava da presença dela. Sentia falta quando ia embora. Queria que estivesse segura.",
      "Kaizen sorriu.",
      "— Estava bem perto.",
      "Arcaceus admitiu que só depois de observar Henrique e Hyejin começara a entender o que sentira.",
      "Se algum dia voltasse àquele universo, havia coisas que gostaria de dizer diferente."
    ]
